/**
 * The Quadradão 1.0's imported art (card NEW-20261022-ORQ-uno-no-jogo): the 8 views of the Uno generated by the Codex
 * (evidence NEW-20261021-ORQ-uno-8-lados, t2, approved by the user; since NEW-20261028-ORQ-uno-capo-fumaca the same car
 * with its hood raised, evidence carro-t1), cut by scripts/import-uno.mjs into one 4×2 sheet of
 * square cells, all at one scale, the wheels on the 85 % line and each view centred. Until the sheet is in (or when it
 * fails) the renderer keeps the provisional boxes (figures.ts).
 * Pure rules (tested): which view shows the car's nose for a heading and a camera view, its scale and its ground anchor.
 */
import {isoOffset} from './iso.ts';
import {CAR_HALF} from './figures.ts';

export const UNO_KEY='chaveiro:quadradao';
export const UNO_URL='/art/lite/veiculos/quadradao.webp';
/** The sheet's square cell (px) and the wheels' line in it (share of the cell from the top). */
export const UNO_CELL=320,UNO_FOOT=.85;
/** The sheet's views in frame order (row 1: S, SO, O, NO; row 2: N, NE, L, SE): where the nose points on the screen. */
export const UNO_VIEWS=['S','SO','O','NO','N','NE','L','SE'] as const;
export type UnoView=typeof UNO_VIEWS[number];
/**
 * World px per sheet px: the diagonal views (a car along a world axis) as wide as the provisional car's footprint,
 * (length + width) × 42 px (SE is 281 px wide in the sheet); the side views come out as long as its body.
 */
export const UNO_SCALE=2*(CAR_HALF.l+CAR_HALF.w)*42/281;

/** Each view's opaque box in the sheet (w × h px, as scripts/import-uno.mjs printed it): centred, its bottom on the wheel line. */
export const UNO_SIZES:Readonly<Record<UnoView,readonly [number,number]>>={
  S:[175,203],SO:[290,216],O:[303,176],NO:[267,213],N:[174,214],NE:[271,213],L:[307,183],SE:[281,220],
};

/**
 * Card NEW-20261028-ORQ-uno-capo-fumaca: the car has broken down, its hood raised (sheet regenerated by the Codex,
 * evidence carro-t1) and smoke rising out of the engine: 16 frames of one loop generated by the Codex on black (evidence
 * fumacad16-t6, the brightness became the alpha), cut by scripts/import-uno-fumaca.mjs into one 8×2 sheet. No drawn smoke.
 */
export const UNO_SMOKE_KEY='chaveiro:uno-fumaca';
export const UNO_SMOKE_URL='/art/lite/veiculos/uno-fumaca.webp';
/** A smoke frame (px), the frames in the loop and its speed: the billows rise ~1/24 of the column per frame. */
export const UNO_SMOKE_W=96,UNO_SMOKE_H=192,UNO_SMOKE_FRAMES=16,UNO_SMOKE_FPS=12;
/** Where the smoke comes out in its frame (px): the same point in all 16. */
export const UNO_SMOKE_SRC=[49.5,180] as const;
/** Sheet px of the car per smoke px: the column is 90 % of the car's cell tall. */
export const UNO_SMOKE_SCALE=.9*UNO_CELL/UNO_SMOKE_H;
/**
 * The engine's mouth in each view (px of the car's cell, read on the sheet): where the smoke comes out. In N, NO and NE
 * the raised hood stands between the camera and the engine, so the smoke rises behind the car.
 */
export const UNO_ENGINE:Readonly<Record<UnoView,readonly [number,number]>>={
  S:[156,178],SO:[88,180],O:[42,172],NO:[55,125],N:[160,70],NE:[258,118],L:[256,162],SE:[200,170],
};
export const UNO_SMOKE_BEHIND:ReadonlySet<UnoView>=new Set<UnoView>(['N','NO','NE']);

/**
 * The smoke for the car's `frame` drawn with its wheel line at (x, y) (world px): the point of the screen where the smoke
 * image's source goes (its origin is UNO_SMOKE_SRC), whether it goes behind the car, and the loop's frame at `time` ms
 * (`still`: reduced effects, one frame).
 */
export function unoSmoke(frame:number,x:number,y:number,time:number,still=false):{x:number;y:number;behind:boolean;frame:number}{
  const v=UNO_VIEWS[frame],[ex,ey]=UNO_ENGINE[v];
  return {x:x+(ex-UNO_CELL/2)*UNO_SCALE,y:y+(ey-UNO_CELL*UNO_FOOT)*UNO_SCALE,behind:UNO_SMOKE_BEHIND.has(v),
    frame:still?0:Math.floor(Math.max(0,time)*UNO_SMOKE_FPS/1000)%UNO_SMOKE_FRAMES};
}

/** The car's box on the screen (world px) for `frame` with its wheel line at (x, y): the life bar and the fade read it. */
export function unoBox(frame:number,x:number,y:number):{x:number;y:number;width:number;height:number}{
  const [w,h]=UNO_SIZES[UNO_VIEWS[frame]],width=w*UNO_SCALE,height=h*UNO_SCALE;
  return {x:x-width/2,y:y-height,width,height};
}

/** Screen octants from the right, clockwise (y down), to the sheet's frames. */
const OCTANT_FRAME=[6,7,0,1,2,3,4,5];

/**
 * The sheet frame of a car at `heading` (radians in the world plane) for the camera `view`: the nose's direction on the
 * screen, the iso squash undone (y × 2) so a car along a world axis takes a diagonal view, cut in 8 octants.
 */
export function unoFrame(heading:number,view:number):number{
  const o=isoOffset(Math.cos(heading),Math.sin(heading),0,view);
  const a=Math.atan2(o.y*2,o.x),octant=((Math.round(a/(Math.PI/4))%8)+8)%8;
  return OCTANT_FRAME[octant];
}

/** The lowest point of the car's footprint below its centre on the screen (px): where the sheet's wheel line sits. */
export function unoFootY(heading:number,view:number):number{
  const c=Math.cos(heading),s=Math.sin(heading);let low=0;
  for(const [u,w] of [[1,1],[1,-1],[-1,1],[-1,-1]]){
    const dx=u*CAR_HALF.l*c-w*CAR_HALF.w*s,dy=u*CAR_HALF.l*s+w*CAR_HALF.w*c;
    low=Math.max(low,isoOffset(dx,dy,0,view).y);
  }
  // the wheels stand a little inside the body's corners
  return low*.85;
}
